    type: 'unary',
    op: '-',
    operand: { type: 'number', value: 2 },
  });

  assert.deepEqual(parseFormula('=+2-3'), {
    type: 'binary',
    op: '-',
    left: {
      type: 'unary',
      op: '+',
      operand: { type: 'number', value: 2 },
    },
    right: { type: 'number', value: 3 },
  });
