import { test } from 'node:test';
import assert from 'node:assert/strict';
import csvCodec from './csv-codec.js';

const { toCsv, fromCsv } = csvCodec;

test('toCsv encodes rows while preserving formula strings', () => {
  assert.equal(
    toCsv([['=A1+1', 'hello'], [2, 'x']]),
    '=A1+1,hello\n2,x',
  );
});

test('toCsv rejects ragged rows', () => {
  assert.throws(
    () => toCsv([['a', 'b'], ['c']]),
    Error,
  );
});

test('toCsv rejects unsupported cell values', () => {
  assert.throws(
    () => toCsv([['ok', true]]),
    Error,
  );
  assert.throws(
    () => toCsv([['ok', null]]),
    Error,
  );
});

test('fromCsv parses unquoted fields', () => {
  assert.deepEqual(
    fromCsv('a,b\n1,2'),
    [['a', 'b'], ['1', '2']],
  );
