test('fromCsv parses quoted fields containing commas and escaped quotes', () => {
  assert.deepEqual(
    fromCsv('"a,b",c'),
    [['a,b', 'c']],
  );
  assert.deepEqual(
    fromCsv('"a""b",c'),
    [['a"b', 'c']],
  );
});

