  number: (value) => ({ type: 'number', value }),
  cell: (row, column) => ({ type: 'cell', row, column }),
  range: (start, end) => ({ type: 'range', start, end }),
  unary: (op, operand) => ({ type: 'unary', op, operand }),
  binary: (op, left, right) => ({ type: 'binary', op, left, right }),
