import { parseAddress, formatAddress } from './cell-address.js';
import { parseFormula } from './formula-parser.js';
import { evaluateFormula } from './formula-evaluator.js';
import { toCsv as encodeCsv, fromCsv as decodeCsv } from './csv-codec.js';

const ERROR_CYCLE = '#CYCLE';

function isFormula(value) {
  return typeof value === 'string' && value.startsWith('=');
}

function isFiniteNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function collectReferences(node, references = []) {
  if (!node || typeof node !== 'object') {
    return references;
  }

  switch (node.type) {
    case 'cell':
      references.push({
        row: node.row,
        column: node.column,
        range: false,
      });
      break;
    case 'range':
      references.push({
        row: node.row,
        column: node.column,
        range: true,
      });
      break;
    case 'unary':
      collectReferences(node.operand, references);
      break;
    case 'binary':
      collectReferences(node.left, references);
      collectReferences(node.right, references);
      break;
    case 'call':
      if (node.range) {
        collectReferences(node.range, references);
      }
      break;
    default:
      break;
  }

  return references;
}

function collectDependencies(node, dependencies = new Set()) {
  for (const reference of collectReferences(node)) {
    if (reference.range) {
      const { start, end } = reference.range;
      const minRow = Math.min(start.row, end.row);
      const maxRow = Math.max(start.row, end.row);
      const minColumn = Math.min(start.column, end.column);
      const maxColumn = Math.max(start.column, end.column);

      for (let row = minRow; row <= maxRow; row += 1) {
        for (let column = minColumn; column <= maxColumn; column += 1) {
          dependencies.add(formatAddress(row, column));
        }
      }
    } else {
      dependencies.add(formatAddress(reference.row, reference.column));
    }
  }

  return dependencies;
}

export class Spreadsheet {
  constructor() {
    this.cells = new Map();
    this.parsed = new Map();
    this.dependencies = new Map();
    this.dependents = new Map();
    this.computed = new Map();
    this.recalculate();
  }

  setCell(address, rawValue) {
    const normalizedAddress = this.#normalizeAddress(address);
    const value = rawValue;

    this.cells.set(normalizedAddress, value);
    this.parsed.delete(normalizedAddress);
    this.dependencies.delete(normalizedAddress);

    for (const dependent of this.dependents.get(normalizedAddress) ?? []) {
      this.dependencies.delete(dependent);
    }
    this.dependents.delete(normalizedAddress);

    this.recalculate();
  }

  getCell(address) {
    const normalizedAddress = this.#normalizeAddress(address);
    const rawValue = this.cells.get(normalizedAddress);

    if (rawValue === undefined) {
      return 0;
    }

    if (isFormula(rawValue)) {
      return this.computed.get(normalizedAddress) ?? 0;
    }

    return rawValue;
  }

  getComputedValue(address) {
    const normalizedAddress = this.#normalizeAddress(address);
    const rawValue = this.cells.get(normalizedAddress);

    if (rawValue === undefined) {
      return 0;
    }

    if (isFormula(rawValue)) {
      return this.computed.get(normalizedAddress) ?? ERROR_CYCLE;
    }

    return rawValue;
  }

  getRawValue(address) {
    const normalizedAddress = this.#normalizeAddress(address);
    return this.cells.get(normalizedAddress);
  }

  getDependencies(address) {
    const normalizedAddress = this.#normalizeAddress(address);
    return [...(this.dependencies.get(normalizedAddress) ?? [])];
  }

  toCsv() {
    let maxRow = -1;
    let maxColumn = -1;

    for (const address of this.cells.keys()) {
      const { row, column } = parseAddress(address);
      maxRow = Math.max(maxRow, row);
      maxColumn = Math.max(maxColumn, column);
    }

    if (maxRow < 0 || maxColumn < 0) {
      return '';
    }

    const rows = [];

    for (let row = 0; row <= maxRow; row += 1) {
      const values = [];

      for (let column = 0; column <= maxColumn; column += 1) {
        values.push(this.getComputedValue(formatAddress(row, column)));
      }

      rows.push(values);
    }

    return encodeCsv(rows);
  }

  fromCsv(src) {
    const rows = decodeCsv(src);

    this.cells.clear();
    this.parsed.clear();
    this.dependencies.clear();
    this.dependents.clear();
    this.computed.clear();

    rows.forEach((row, rowIndex) => {
      row.forEach((field, columnIndex) => {
        const address = formatAddress(rowIndex, columnIndex);
        const numericValue = typeof field === 'string' && field.trim() !== ''
          ? Number(field)
          : NaN;

        this.cells.set(
          address,
          Number.isFinite(numericValue) ? numericValue : field,
        );
      });
    });

    this.recalculate();
  }

  recalculate() {
    this.parsed.clear();
    this.dependencies.clear();
    this.dependents.clear();

    const formulaAddresses = [];

    for (const [address, rawValue] of this.cells) {
      if (!isFormula(rawValue)) {
        continue;
      }

      let ast;

      try {
        ast = parseFormula(rawValue);
      } catch {
        ast = null;
      }

      this.parsed.set(address, ast);
      formulaAddresses.push(address);

      if (ast) {
        const dependencies = collectDependencies(ast);

        for (const dependency of dependencies) {
          this.dependencies.set(address, dependencies);
          if (!this.dependents.has(dependency)) {
            this.dependents.set(dependency, new Set());
          }
          this.dependents.get(dependency).add(address);
        }
      }
    }

    const values = new Map();

    for (const [address, rawValue] of this.cells) {
      if (!isFormula(rawValue)) {
        values.set(address, rawValue);
      }
    }

    const graph = new Map();

    for (const address of formulaAddresses) {
      graph.set(address, this.dependencies.get(address) ?? new Set());
    }

    const visiting = new Set();
    const visited = new Set();
    const cycleCells = new Set();

    const visit = (address) => {
      if (visited.has(address)) {
        return;
      }

      if (visiting.has(address)) {
        cycleCells.add(address);
        return;
      }

      visiting.add(address);

      for (const dependency of graph.get(address) ?? []) {
        if (graph.has(dependency)) {
          visit(dependency);
        }
      }

      visiting.delete(address);
      visited.add(address);
    };

    for (const address of formulaAddresses) {
      visit(address);
    }

    const evaluateAddress = (address) => {
      if (cycleCells.has(address)) {
        return ERROR_CYCLE;
      }

      const rawValue = this.cells.get(address);
      const ast = this.parsed.get(address);

      if (!ast) {
        return '#CYCLE';
      }

      const context = {
        getCell: (row, column) => {
          const reference = formatAddress(row, column);
          const value = values.get(reference);

          if (value === undefined) {
            return 0;
          }

          if (value === ERROR_CYCLE || value === '#DIV/0') {
            return value;
          }

          return value;
        },
        getRange: (start, end) => {
          const minRow = Math.min(start.row, end.row);
          const maxRow = Math.max(start.row, end.row);
          const minColumn = Math.min(start.column, end.column);
          const maxColumn = Math.max(start.column, end.column);
          const rangeValues = [];

          for (let row = minRow; row <= maxRow; row += 1) {
            for (let column = minColumn; column <= maxColumn; column += 1) {
              const reference = formatAddress(row, column);
              const value = values.get(reference);

              if (value === undefined) {
                rangeValues.push(0);
              } else {
                rangeValues.push(value);
              }
            }
          }

          return rangeValues;
        },
      };

      try {
        const result = evaluateFormula(ast, context);
        return result === undefined ? 0 : result;
      } catch {
        return ERROR_CYCLE;
      }
    };

    const evaluateInOrder = (address) => {
      if (values.has(address) && this.cells.get(address) !== undefined) {
        const rawValue = this.cells.get(address);
        if (!isFormula(rawValue)) {
          return;
        }
      }

      if (visited.has(address)) {
        return;
      }

      visiting.add(address);

      for (const dependency of graph.get(address) ?? []) {
        if (graph.has(dependency)) {
          evaluateInOrder(dependency);
        }
      }

      visiting.delete(address);
      visited.add(address);

      if (cycleCells.has(address)) {
        values.set(address, ERROR_CYCLE);
      } else {
        values.set(address, evaluateAddress(address));
      }
    };

    for (const address of formulaAddresses) {
      if (!visited.has(address)) {
        evaluateInOrder(address);
      }
    }

    this.computed = new Map();

    for (const [address, value] of values) {
      if (isFormula(this.cells.get(address))) {
        this.computed.set(address, value);
      }
    }
  }

  #normalizeAddress(address) {
    if (typeof address !== 'string') {
      throw new Error('Invalid cell address');
    }

    const parsed = parseAddress(address.trim().toUpperCase());
    return formatAddress(parsed.row, parsed.column);
  }
}
